function canSee(guard, target) {
  const dx = target.x - guard.x, dy = target.y - guard.y;
  if (Math.hypot(dx, dy) > guard.range) return false;
  const deg = Math.atan2(dy, dx) * 180 / Math.PI;
  const diff = ((deg - guard.facing) % 360 + 540) % 360 - 180;
  return Math.abs(diff) <= guard.fov / 2;
}

