stages.s:
const TURN_SPEED = 180, THRUST = 100, MAX_SPEED = 200;
function shipTick(ship, input, dt) {
  let angle = ship.angle + input.turn * TURN_SPEED * dt;
  angle = ((angle % 360) + 360) % 360;
  let vx = ship.vx, vy = ship.vy;
  if (input.thrust) {
    const a = angle * Math.PI / 180;
    vx += Math.cos(a) * THRUST * dt;
    vy += Math.sin(a) * THRUST * dt;
  }
  const speed = Math.hypot(vx, vy);
  if (speed > MAX_SPEED) {
    vx *= MAX_SPEED / speed;
    vy *= MAX_SPEED / speed;
  }
  return { x: ship.x + vx * dt, y: ship.y + vy * dt, vx, vy, angle };
}

